g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
h,w=len(g),len(g[0]); seen=set()
for r in range(h):
 for c in range(w):
  if g[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); cells=[]; border=set()
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w:
      if g[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
      elif g[a][b]!=0:border.add(g[a][b])
   touch=any(x in (0,h-1) or y in (0,w-1) for x,y in cells)
   print(len(cells),'bounds',min(x for x,y in cells)+1,max(x for x,y in cells)+1,min(y for x,y in cells)+1,max(y for x,y in cells)+1,'touch',touch,'border',border,'coords',[(x+1,y+1) for x,y in cells])
